function stringFlags(g: O3, B: Builder, a: number[], b: number[], n: number, mats: Mat[], sag = 0.35) {
  const dx = b[0] - a[0],
    dz = b[2] - a[2],
    phi = Math.atan2(-dz, dx);
  let prev = null;
  for (let i = 0; i <= n; i++) {
    const t = i / n,
      p = [a[0] + dx * t, a[1] - sag * 4 * t * (1 - t), a[2] + dz * t];
    if (prev) B.wire(prev, p);
    prev = p;
    if (i > 0 && i < n) {
      const f = noSh(mesh(g, new THREE.PlaneGeometry(0.22, 0.3), mats[i % mats.length], p[0], p[1] - 0.16, p[2]));
      f.rotation.y = phi;
    }
  }
}
