const txtT = (txt: string, o: { bg?: string; border?: string; c?: string; s?: number; f?: string; f1?: string; f2?: string } = {}) =>
  T(
    (x, w, h) => {
      x.fillStyle = o.bg || '#f6f1e8';
      x.fillRect(0, 0, w, h);
      if (o.border) {
        x.strokeStyle = o.border;
        x.lineWidth = 6;
        x.strokeRect(14, 14, w - 28, h - 28);
      }
      x.fillStyle = o.c || '#2a2420';
      x.textAlign = 'center';
      x.textBaseline = 'middle';
      const L = txt.split('\n');
      L.forEach((l, i) => {
        x.font = i === 0 ? o.f1 || 'italic 64px Georgia, serif' : o.f2 || '26px Georgia, serif';
        x.fillText(l, w / 2, h / 2 + (i - (L.length - 1) / 2) * (i ? 40 : 70));
      });
    },
    [1, 1],
    o.s || 256,
  );
