const PSIZE = (a: string[]): Array<[string, string]> => a.map((v) => [v, v.replace('x', ' × ') + ' m']);
const cX = (g: O3, x0: number, x1: number, y: number, z: number, r: number, m: Mat) => {
  const c = cyl(g, r, r, Math.abs(x1 - x0), m, (x0 + x1) / 2, y, z, 8);
  c.rotation.z = Math.PI / 2;
  return c;
};
const cZ = (g: O3, z0: number, z1: number, y: number, x: number, r: number, m: Mat) => {
  const c = cyl(g, r, r, Math.abs(z1 - z0), m, x, y, (z0 + z1) / 2, 8);
  c.rotation.x = Math.PI / 2;
  return c;
};
const trussM = M('#c8c8cc', 0.3, 0.9);
function trussBeam(g: O3, x0: number, x1: number, y: number, z: number) {
  for (const dy of [0, 0.29]) for (const dz of [-0.145, 0.145]) cX(g, x0, x1, y + dy, z + dz, 0.018, trussM);
  const n = Math.max(2, Math.round(Math.abs(x1 - x0) / 0.3));
  for (let i = 0; i <= n; i++) {
    const x = x0 + ((x1 - x0) * i) / n;
    box(g, 0.012, 0.29, 0.012, trussM, x, y + 0.145, z - 0.145);
    box(g, 0.012, 0.29, 0.012, trussM, x, y + 0.145, z + 0.145);
  }
}
function trussLeg(g: O3, x: number, z: number, h: number) {
  for (const a of [-0.145, 0.145]) for (const b of [-0.145, 0.145]) cyl(g, 0.018, 0.018, h, trussM, x + a, h / 2, z + b, 8);
  box(g, 0.6, 0.02, 0.6, trussM, x, 0.01, z);
  for (let y = 0.3; y < h; y += 0.45) box(g, 0.3, 0.012, 0.3, trussM, x, y, z);
}
